import React, { useState } from "react";
import "./JobItem.css";

const JobItem = ({ job, onDelete, onStatusChange }) => {
  const [editing, setEditing] = useState(false);
  const [newStatus, setNewStatus] = useState(job.status || "Applied");

  const handleUpdate = () => {
    onStatusChange(job._id, newStatus);
    setEditing(false);
  };

  return (
    <div className="job-item">
      <div>
        <h3>{job.company}</h3>
        <p><strong>Position:</strong> {job.position}</p>
        <p><strong>Date:</strong> {new Date(job.date).toLocaleDateString()}</p>
        <p><strong>Status:</strong> {job.status}</p>
        {job.link && (
          <p>
            <strong>Link: </strong>
            <a href={job.link} target="_blank" rel="noopener noreferrer">
              View Job Posting
            </a>
          </p>
        )}
      </div>

      <div className="actions">
        {editing ? (
          <>
            <select
              value={newStatus}
              onChange={(e) => setNewStatus(e.target.value)}
            >
              <option value="Applied">Applied</option>
              <option value="Interview">Interview</option>
              <option value="Offer">Offer</option>
              <option value="Rejected">Rejected</option>
            </select>
            <button className="update-btn" onClick={handleUpdate}>Update</button>
            <button className="cancel-btn" onClick={() => setEditing(false)}>Cancel</button>
          </>
        ) : (
          <>
            <button className="edit-btn" onClick={() => setEditing(true)}>Edit</button>
            <button className="delete-btn" onClick={() => onDelete(job._id)}>Delete</button>
          </>
        )}
      </div>
    </div>
  );
};

export default JobItem;
